<?php $isHistory=!empty($deliverySearch['history']); $listPage=$isHistory?'history':'deliveries'; $pendingOnly=!empty($deliverySearch['pendingOnly']); $filter=$isHistory ? '' : '&amp;f=' . ($pendingOnly ? 'pending' : 'all');
// Plazo de respuesta informado al paciente (24 h por defecto) contado desde la creación de la solicitud.
$slaHours=(int)$app->config['whatsapp_estimated_hours'];
$sla=function(array $row) use ($slaHours): array { $left=strtotime($row['created_at'])+$slaHours*3600-time(); $h=intdiv(abs($left),3600); $m=intdiv(abs($left)%3600,60);
  if ($left<0) return ['late','Vencida','hace '.($h?$h.' h ':'').$m.' min']; return [$left<6*3600?'soon':'ok',$left<6*3600?'Por vencer':'A tiempo','quedan '.($h?$h.' h ':'').$m.' min']; }; ?>
<section class="card spaced" id="deliveries"><h2><?= $isHistory ? 'Historial de historias enviadas' : 'Solicitudes' ?></h2><p class="muted"><?= $isHistory ? 'Solicitudes aprobadas automáticamente y con envío aceptado por el servidor de correo. Los casos reabiertos pasan a Solicitudes hasta completar un nuevo envío.' : ($pendingOnly ? 'Solicitudes sin historia enviada, de la más antigua a la más reciente. El paciente recibió un tiempo estimado de respuesta de ' . $slaHours . ' horas. Abre cada una para asignar la historia, cargar el PDF o responder «No registra».' : 'Todas las solicitudes: busca al paciente y consulta el seguimiento de su historia clínica.') ?></p>
<?php if (!$isHistory): ?><nav class="segmented" aria-label="Filtro de solicitudes"><a href="?page=deliveries&amp;f=pending&amp;q=<?= rawurlencode($deliverySearch['query']) ?>" <?= $pendingOnly ? 'aria-current="page"' : '' ?>>Pendientes<?php if (!empty($pendingCount)): ?> (<?= (int)$pendingCount ?>)<?php endif ?></a><a href="?page=deliveries&amp;f=all&amp;q=<?= rawurlencode($deliverySearch['query']) ?>" <?= !$pendingOnly ? 'aria-current="page"' : '' ?>>Todas</a></nav><?php endif ?>
<form method="get" class="delivery-search"><input type="hidden" name="page" value="<?= $listPage ?>"><?php if (!$isHistory): ?><input type="hidden" name="f" value="<?= $pendingOnly ? 'pending' : 'all' ?>"><?php endif ?><label for="delivery-query">Nombre, radicado o número de documento<input id="delivery-query" type="search" name="q" maxlength="160" placeholder="Ej.: nombre completo, HC-… o cédula" value="<?= h($deliverySearch['query']) ?>"></label><button class="button primary" type="submit">Buscar</button><?php if ($deliverySearch['query'] !== ''): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>">Limpiar</a><?php endif ?></form>
<p class="muted" role="status"><?= (int)$deliverySearch['total'] ?> solicitud(es)<?= $deliverySearch['query'] !== '' ? ' para «' . h($deliverySearch['query']) . '»' : '' ?>.</p>
<?php if (!$deliverySearch['rows']): ?><div class="empty-state"><?= $pendingOnly && $deliverySearch['query'] === '' ? 'No hay solicitudes pendientes. Todas tienen historia enviada o una respuesta.' : ($isHistory ? 'No hay historias enviadas que coincidan con la búsqueda. Las entregas simuladas o fallidas no aparecen en este historial.' : 'No se encontraron solicitudes con esos datos. Prueba con parte del nombre, el radicado o el documento.') ?></div>
<?php else: ?>
<?php if ($isHistory): require __DIR__ . '/delivery-history-rows.php'; else: ?><div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Paciente</th><th scope="col" role="columnheader">Radicado / fecha</th><th scope="col" role="columnheader">Correo de entrega</th><?php if ($pendingOnly): ?><th scope="col" role="columnheader">Plazo</th><?php endif ?><th scope="col" role="columnheader">Estado</th><th scope="col" role="columnheader">Envíos</th><th scope="col" role="columnheader">Ver</th></tr></thead><tbody role="rowgroup">
<?php foreach ($deliverySearch['rows'] as $row): ?><tr role="row"><td role="cell" data-label="Paciente"><strong><?= h($row['claimed_name']) ?></strong><small><?= $row['document_number'] ? h($row['document_type'].' '.$row['document_number']) : 'Documento no conservado en esta solicitud antigua' ?></small></td><td role="cell" data-label="Radicado / fecha"><?= h($row['reference']) ?><small><?= h($row['created_at']) ?></small></td><td role="cell" data-label="Correo de entrega" class="delivery-email"><?= h($row['contact_email'] ?? '—') ?></td><?php if ($pendingOnly): [$slaClass,$slaLabel,$slaText]=$sla($row); ?><td role="cell" data-label="Plazo"><span class="pill sla-<?= $slaClass ?>"><?= $slaLabel ?></span><small><?= h($slaText) ?></small></td><?php endif ?><td role="cell" data-label="Estado"><?php if (!empty($row['whatsapp_phone'])): ?><span class="pill channel">WhatsApp</span><?php endif ?><?php if ($row['case_pending']): ?><span class="pill case-pending">Pendiente de gestión</span><small>Reabierto <?= h($row['case_reopened_at']) ?></small><?php endif ?><span class="pill"><?= h($labels[$row['status']] ?? $row['status']) ?></span><?php if ($row['last_error']): ?><small class="danger">Último envío con error</small><?php endif ?></td><td role="cell" data-label="Envíos"><?= (int)$row['deliveries'] ?></td><td role="cell" data-label="Ver"><a class="button secondary eye-button" data-delivery-modal aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$row['id'] ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= (int)$deliverySearch['page'] ?>" aria-label="Ver envío de <?= h($row['reference']) ?>" title="Ver detalle del envío"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></a></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
<nav class="delivery-pagination" aria-label="Páginas de solicitudes"><?php if ($deliverySearch['page']>1): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']-1 ?>">← Anterior</a><?php endif ?><span class="muted">Página <?= (int)$deliverySearch['page'] ?> de <?= (int)$deliverySearch['pages'] ?></span><?php if ($deliverySearch['page']<$deliverySearch['pages']): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']+1 ?>">Siguiente →</a><?php endif ?></nav>
<?php endif ?></section>
<dialog id="delivery-modal" class="delivery-modal" aria-labelledby="delivery-modal-title">
<div class="delivery-modal-header"><div class="case-head"><span class="case-head-icon" aria-hidden="true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/></svg></span><div><h2 id="delivery-modal-title">Detalle del envío</h2><small>Expediente de atención</small></div></div><button class="case-close" type="button" data-close-delivery aria-label="Cerrar detalle del envío"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>
<div class="delivery-modal-content" data-delivery-content aria-live="polite"></div>
</dialog>
